// ponytail: the backend owns collection, validation and retries; this branch reports source outcomes only.
const sources=['gsc','ga4','meta','ubersuggest'];
const results=sources.map(source=>{
  const body=$('Daily · '+source.toUpperCase()).first().json;
  const row=Array.isArray(body.results)?body.results.find(x=>x.source===source):null;
  return {source,status:row?.status??'failed',batchId:typeof row?.batchId==='string'?row.batchId:null};
});
const outcome=$('Daily · ประเมินด้วย VPS AI').first().json;
const assessment={state:typeof outcome.state==='string'?outcome.state:'unavailable',jobId:typeof outcome.jobId==='string'?outcome.jobId:null,reused:outcome.reused===true};
if(results.some(row=>!['completed','duplicate'].includes(row.status))) throw new Error('ANALYTICS_DAILY_INCOMPLETE');
if(!['queued','leased','succeeded','skipped'].includes(assessment.state)) throw new Error('ANALYTICS_ASSESSMENT_INCOMPLETE');
return [{json:{collectedAt:new Date().toISOString(),results,assessment}}];

// Only stage metadata is emitted; source rows and customer data never enter AI orchestration.
const names=['Marketing Daily · Canonical Identity','Marketing Daily · GSC 7 วัน','Marketing Daily · GA4 7 วัน','Marketing Daily · วัดผลก่อน–หลัง'];
const stages=names.map(name=>{const body=$(name).first().json;return {stage:name,status:typeof body.status==='string'?body.status:'unavailable',errorCategory:body.error?'marketing-refresh-failed':null};});
return [{json:{factsRemainAvailable:true,stages,completedAt:new Date().toISOString()}}];

