const status=typeof body.status==='string'?body.status:'unavailable';
const attempt=$runIndex+1;
// ponytail: allow one local repair before the Neon-gated Cloud path.
return [{json:{status,workerSucceeded:body.workerSucceeded===true,attempt,canRetry:['prepared','queued','running'].includes(status)&&attempt<16,factsRemainAvailable:true}}];

