const factual=$('Marketing Daily · ตรวจผล factual').first().json;
const ai=['Marketing AI Weekly · บันทึกสถานะขั้น','Marketing AI Monthly · บันทึกสถานะขั้น'].map(name=>$(name).first().json);
return [{json:{completedAt:new Date().toISOString(),factsRemainAvailable:true,stages:factual.stages,ai,status:factual.stages.some(item=>!['completed','duplicate','ready'].includes(item.status))||ai.some(item=>item.errorCategory!==null)?'needs-review':ai.some(item=>!item.validated)?'pending':'completed',reviewRequired:factual.stages.some(item=>!['completed','duplicate','ready'].includes(item.status))||ai.some(item=>item.errorCategory!==null)}}];

const response=$input.first().json;
const reservation=$('Marketing AI Weekly · จอง Cloud').first().json;
const review=reservation.mode==='review';
const base={analysisId:reservation.analysisId,inputHash:reservation.inputHash,reservationId:reservation.reservationId,...(review?{localOutputDigest:reservation.localOutputDigest}:{})};
const fail=reason=>[{json:{operation:review?'failReview':'failCloud',...base,reason}}];
if(response.error||response.statusCode>=400||response.status!=='completed'){
const errorText=typeof response.error==='string'?response.error:response.error&&typeof response.error==='object'?JSON.stringify(response.error):'';
const statusFromText=errorText.match(/^\s*([1-5]\d\d)\b/);
const httpStatus=[response.statusCode,response.httpStatus,response.error?.statusCode,response.error?.httpCode,response.error?.status].map(Number).find(value=>Number.isInteger(value)&&value>=100&&value<=599)??(statusFromText?Number(statusFromText[1]):null);
const codeFromText=errorText.replace(/\\"/g,'"').match(/"code"\s*:\s*"([A-Za-z][A-Za-z0-9_-]{0,47})"/);
const rawCode=response.error?.code??response.body?.error?.code??response.error?.error?.code??codeFromText?.[1];
const errorCode=typeof rawCode==='string'&&/^[A-Za-z][A-Za-z0-9_-]{0,47}$/.test(rawCode)?rawCode:null;
const rawIncomplete=response.incomplete_details?.reason;
const incompleteReason=typeof rawIncomplete==='string'&&/^[A-Za-z][A-Za-z0-9_-]{0,47}$/.test(rawIncomplete)?rawIncomplete:null;
console.log(JSON.stringify({event:'marketing-cloud-weekly-http',httpStatus,errorCode,incompleteReason}));
return fail('api-error');}
const parts=Array.isArray(response.output)?response.output.flatMap(x=>Array.isArray(x.content)?x.content:[]):[];
const raw=typeof response.output_text==='string'?response.output_text:parts.find(x=>x.type==='output_text'&&typeof x.text==='string')?.text;
const usage=response.usage;
if(typeof raw!=='string'||!Number.isInteger(usage?.input_tokens)||!Number.isInteger(usage?.output_tokens)||response.store!==false)return fail('model-output-invalid');
try{const parsed=JSON.parse(raw);return [{json:{operation:review?'submitReview':'submitCloud',...base,...(review?{verdict:parsed}:{selection:parsed}),usage:{inputTokens:usage.input_tokens,outputTokens:usage.output_tokens}}}];}
catch{return fail('model-output-invalid');}

